package com.gameaggregator.ledgerservice.api;import jakarta.validation.constraints.*;import java.math.BigDecimal;import java.time.*;import java.util.UUID;public final class LedgerDtos{private LedgerDtos(){}public record Transaction(@NotBlank String idempotencyKey,@NotNull UUID clientId,@NotNull UUID gameId,@NotNull BigDecimal amount,@Pattern(regexp="[A-Z]{3}")String currency,@NotNull Instant occurredAt){}public record Allocation(@NotNull UUID beneficiaryId,@Pattern(regexp="PLATFORM|STUDIO|PUBLISHER|CLIENT")String beneficiaryType,@NotNull BigDecimal amount){}public record AdjustmentRequest(@NotBlank String idempotencyKey,@NotNull BigDecimal amountDelta,@NotBlank String reason,@NotNull UUID createdBy){}public record SettlementRequest(@NotNull UUID beneficiaryId,@NotNull LocalDate periodFrom,@NotNull LocalDate periodTo,@NotNull BigDecimal amount){}}